export interface Filters {
  query: string;
  tags: string[];
  priceMin?: number;
  priceMax?: number;
  sort: Sort;
  page: number;
}

export const DEFAULT_SORT: Sort = 'relevance';
export const DEFAULT_PAGE = 1;

const SORTS: Sort[] = ['relevance', 'price_asc', 'price_desc'];

function isDefault(state: Filters): boolean {
  return (
    state.query === '' &&
    state.tags.length === 0 &&
    state.priceMin === undefined &&
    state.priceMax === undefined &&
    state.sort === DEFAULT_SORT &&
    state.page === DEFAULT_PAGE
  );
}

/** Serialize filter state to compact URL params, omitting defaults entirely. */
export function serializeFilters(state: Filters): URLSearchParams {
  const p = new URLSearchParams();

  if (state.query !== '') p.set('q', state.query);

  for (const tag of state.tags) p.append('tag', tag);

  if (state.priceMin !== undefined && Number.isFinite(state.priceMin)) {
    p.set('min', String(state.priceMin));
  }
  if (state.priceMax !== undefined && Number.isFinite(state.priceMax)) {
    p.set('max', String(state.priceMax));
  }

  if (state.sort !== DEFAULT_SORT) p.set('sort', state.sort);
  if (state.page !== DEFAULT_PAGE) p.set('page', String(state.page));

  return p;
}

/**
 * Parse filters from URLSearchParams.
 * - Bad/missing numerics coerce and clamp to defaults (never NaN).
 * - Unknown params ignored; unknown sort falls back to relevance.
 * - Round-trips canonical states produced by serializeFilters.
 */
export function parseFilters(searchParams: URLSearchParams): Filters {
  // query: last value wins on duplicates
  const query = searchParams.get('q') ?? '';

  // tags: all repeated values
  const tags = [...new Set(searchParams.getAll('tag'))].filter(
    (t) => t.length > 0,
  );

  // priceMin / priceMax: coerce, reject non-finite/negative, drop junk
  let priceMin: number | undefined;
  let priceMax: number | undefined;
  const minRaw = searchParams.get('min');
  if (minRaw !== null) {
    const n = Number(minRaw);
    if (Number.isFinite(n) && n >= 0) priceMin = Math.round(n);
  }
  const maxRaw = searchParams.get('max');
  if (maxRaw !== null) {
    const n = Number(maxRaw);
    if (Number.isFinite(n) && n >= 0) priceMax = Math.round(n);
  }
  // Drop inverted range rather than producing a nonsensical filter
  if (priceMin !== undefined && priceMax !== undefined && priceMin > priceMax) {
    [priceMin, priceMax] = [priceMax, priceMin];
  }

  // sort: only known values
  const sortRaw = searchParams.get('sort');
  const sort: Sort =
    sortRaw !== null && (SORTS as string[]).includes(sortRaw)
      ? (sortRaw as Sort)
      : DEFAULT_SORT;

  // page: coerce to positive integer >= 1
  let page = DEFAULT_PAGE;
  const pageRaw = searchParams.get('page');
  if (pageRaw !== null) {
    const n = Number(pageRaw);
    if (Number.isFinite(n)) {
      page = Math.max(DEFAULT_PAGE, Math.floor(n));
    }
  }

  return { query, tags, priceMin, priceMax, sort, page };
}

/** Canonicalize arbitrary input state into the exact shape round-trip guarantees. */
export function canonicalize(state: Partial<Filters>): Filters {
  const query = typeof state.query === 'string' ? state.query : '';
  const tags = Array.isArray(state.tags)
    ? [...new Set(state.tags.filter((t) => typeof t === 'string' && t.length > 0))]
    : [];
  const num = (v: unknown): number | undefined =>
    typeof v === 'number' && Number.isFinite(v) && v >= 0 ? Math.round(v) : undefined;
  let priceMin = num(state.priceMin);
  let priceMax = num(state.priceMax);
  if (priceMin !== undefined && priceMax !== undefined && priceMin > priceMax) {
    [priceMin, priceMax] = [priceMax, priceMin];
  }
  const sort: Sort =
    typeof state.sort === 'string' && (SORTS as string[]).includes(state.sort)
      ? (state.sort as Sort)
      : DEFAULT_SORT;
  const page =
    typeof state.page === 'number' && Number.isFinite(state.page)
      ? Math.max(DEFAULT_PAGE, Math.floor(state.page))
      : DEFAULT_PAGE;
  return { query, tags, priceMin, priceMax, sort, page };
}

// Re-serialize canonical output to guarantee byte-stable round trips.
export function normalizeViaUrl(state: Partial<Filters>): Filters {
  return parseFilters(serializeFilters(canonicalize(state)));
}

export { isDefault };
