result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/url-state/src/index.test.ts", "content": "import { describe, it, expect } from 'vitest';
import {
  serializeFilters,
  parseFilters,
  type Filters,
  type Sort,
} from './index.js';

// ---------------------------------------------------------------------------
// Deterministic RNG (mulberry32) so failures are reproducible
// ---------------------------------------------------------------------------
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SORTS: Sort[] = ['relevance', 'price_asc', 'price_desc'];
const ALPHABET = 'abcXYZ 09-_~.*!()é漢字&+=?#/%:"\'<>[]{}';

function pick<T>(rnd: () => number, arr: readonly T[]): T {
  return arr[Math.floor(rnd() * arr.length)];
}

function randomString(rnd: () => number, maxLen = 12): string {
  const len = Math.floor(rnd() * (maxLen + 1));
  let s = '';
  for (let i = 0; i < len; i++) s += pick(rnd, [...ALPHABET]);
  return s;
}

/** Generate a canonical state: exactly what parse(serialize(s)) must equal. */
function randomCanonicalState(rnd: () => number): Filters {
  const tags: string[] = [];
  const nTags = Math.floor(rnd() * 4); // 0..3
  for (let i = 0; i < nTags; i++) {
    const tag = randomString(rnd).trim();
    if (tag.length > 0 && !tags.includes(tag)) tags.push(tag);
  }
  let priceMin: number | undefined;
  let priceMax: number | undefined;
  if (rnd() < 0.5) priceMin = Math.floor(rnd() * 1000);
  if (rnd() < 0.5) priceMax = Math.floor(rnd() * 1000);
  if (priceMin !== undefined && priceMax !== undefined && priceMin > priceMax) {
    [priceMin, priceMax] = [priceMax, priceMin];
  }
  return {
    query: randomString(rnd),
    tags,
    priceMin,
    priceMax,
    sort: pick(rnd, SORTS),
    page: 1 + Math.floor(rnd() * 50),
  };
}

describe('serializeFilters / parseFilters', () => {
  it('round-trips 200 randomized canonical states', () => {
    const rnd = mulberry32(0xc0ffee);
    for (let i = 0; i < 200; i++) {
      const state = randomCanonicalState(rnd);
      const params = serializeFilters(state);
      // sanity: params string is compact & clean
      expect(params.toString()).not.toMatch(/=(?:&|$)/); // no empty values
      const back = parseFilters(new URLSearchParams(params));
      expect(back).toEqual(state);
    }
  });

  it('omits defaults entirely so default-state serializes to empty', () => {
    const empty: Filters = {
      query: '',
      tags: [],
      priceMin: undefined,
      priceMax: undefined,
      sort: 'relevance',
      page: 1,
    };
    expect(serializeFilters(empty).toString()).toBe('');

    // individual defaults omitted
    const onlySort: Filters = { ...empty, sort: 'price_asc' };
    expect([...serializeFilters(onlySort).keys()].sort()).toEqual(['sort']);

    const onlyPage: Filters = { ...empty, page: 3 };
    expect([...serializeFilters(onlyPage).keys()]).toEqual(['page']);

    const onlyQuery: Filters = { ...empty, query: 'socks' };
    expect([...serializeFilters(onlyQuery).keys()]).toEqual(['q']);
  });

  it('repeats tag param once per tag and preserves order', () => {
    const state: Filters = {
      query: '',
      tags: ['red', 'blue'],
      priceMin: undefined,
      priceMax: undefined,
      sort: 'relevance',
      page: 1,
    };
    const p = serializeFilters(state);
    expect(p.getAll('tag')).toEqual(['red', 'blue']);
    expect(parseFilters(p)).toEqual(state);
  });

  it('hostile: page=-3 clamps to default page 1', () => {
    const p = new URLSearchParams('q=x&page=-3');
    expect(parseFilters(p).page).toBe(1);
    expect(parseFilters(new URLSearchParams('page=0')).page).toBe(1);
    expect(parseFilters(new URLSearchParams('page=2.9')).page).toBe(2);
  });

  it('hostile: min=abc yields undefined priceMin, not NaN', () => {
    const r = parseFilters(new URLSearchParams('min=abc'));
    expect(r.priceMin).toBeUndefined();
    expect(Number.isNaN(r.priceMin as unknown as number)).toBe(false);

    expect(parseFilters(new URLSearchParams('max=1e999')).priceMax).toBeUndefined(); // Infinity -> dropped
    expect(parseFilters(new URLSearchParams('min=')).priceMin).toBeUndefined();
    expect(parseFilters(new URLSearchParams('min=-5')).priceMin).toBeUndefined();
  });

  it('hostile: duplicate q — last value wins deterministically', () => {
    // URLSearchParams.get returns the first value; spec our contract:
    // parsing must be deterministic. We document first-value-wins via get().
    const p = new URLSearchParams();
    p.append('q', 'first');
    p.append('q', 'second');
    const r = parseFilters(p);
    expect(['first', 'second']).toContain(r.query);
    // round-trip stable: re-serializing gives exactly one q
    expect(serializeFilters(r).getAll('q')).toHaveLength(1);
  });

  it('hostile: duplicate numeric params coerce to one value', () => {
    const p = new URLSearchParams();
    p.append('min', '10');
    p.append('min', 'junk');
    const r = parseFilters(p);
    expect(r.priceMin).toBeDefined();
    expect(r.priceMin).not.toBeNaN();
  });

  it('hostile: unknown params ignored', () => {
    const p = new URLSearchParams(
      'q=hat&utm_source=email&foo=bar&tag=x&sessionid=zzz',
    );
    const r = parseFilters(p);
    expect(r.query).toBe('hat');
    expect(r.tags).toEqual(['x']);
    expect(Object.keys(r)).toEqual([
      'query',
      'tags',
      'priceMin',
      'priceMax',
      'sort',
      'page',
    ]);
  });

  it('hostile: garbage everywhere still yields a valid default-ish state', () => {
    const inputs = [
      '',
      '&&&',
      'page=abc&min=xyz&max=%FF&sort=nonsense',
      'page=-99&page=nope',
      'min=NaN&max=Infinity',
      'q=%E0%A4%A',
      'sort=PRICE_ASC',
    ];
    for (const s of inputs) {
      const r = parseFilters(new URLSearchParams(s));
      expect(r.page).toBeGreaterThanOrEqual(1);
      expect(Number.isFinite(r.priceMin ?? 0)).toBe(true);
      expect(Number.isFinite(r.priceMax ?? 0)).toBe(true);
      expect(['relevance', 'price_asc', 'price_desc']).toContain(r.sort);
      expect(typeof r.query).toBe('string');
      expect(Array.isArray(r.tags)).toBe(true);
    }
    expect(parseFilters(new URLSearchParams('sort=PRICE_ASC')).sort).toBe(
      'relevance',
    );
    expect(parseFilters(new URLSearchParams('sort=price_desc')).sort).toBe(
      'price_desc',
    );
  });

  it('inverted min/max range is normalized consistently both directions', () => {
    const state: Filters = {
      query: '',
      tags: [],
      priceMin: 100,
      priceMax: 10,
      sort: 'relevance',
      page: 1,
    };
    const back = parseFilters(serializeFilters(state));
    expect(back.priceMin!).toBeLessThanOrEqual(back.priceMax!);
    // and that output is itself stable under another round-trip
    expect(parseFilters(serializeFilters(back))).toEqual(back);
  });

  it('special characters in query and tags survive encoding', () => {
    const state: Filters = {
      query: 'a b&c=d?e#f%20g+ü漢',
      tags: ['tag/with slash', 'a=b', '&weird&'],
      priceMin: undefined,
      priceMax: undefined,
      sort: 'relevance',
      page: 1,
    };
    expect(parseFilters(new URLSearchParams(serializeFilters(state)))).toEqual(
      state,
    );
  });
});
